    int fileSize = averageFileSize(table);
    List<Object[]> originalData = currentData();
    BaseRewriteDataFilesSparkAction realRewrite = (org.apache.iceberg.spark.actions.BaseRewriteDataFilesSparkAction) basicRewrite(table).option(RewriteDataFiles.MAX_FILE_GROUP_SIZE_BYTES, Integer.toString(fileSize * 2 + 100)).option(RewriteDataFiles.PARTIAL_PROGRESS_ENABLED, "true").option(RewriteDataFiles.PARTIAL_PROGRESS_MAX_COMMITS, "3");
    BaseRewriteDataFilesSparkAction spyRewrite = Mockito.spy(realRewrite);
    // Fail groups 1, 3, and 7 during rewrite
